files.starterContent:
body {
  display: grid;
  place-content: center;
  gap: 24px;
  min-height: 100vh;
  margin: 0;
  font: 16px system-ui, sans-serif;
  background: #111;
  color: #eee;
}

.lamp {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background: #2a2a2a;
  transition: background 150ms ease;
}

.lamp.on {
  background: #ffd76a;
}

button {
  padding: 8px 16px;
  border: 1px solid #444;
  border-radius: 4px;
  background: transparent;
  color: inherit;
  cursor: pointer;
}

